arguments.command:
python - <<'EOF'
from app.boot import boot, BootError

# valid config still boots
assert boot({"service": {"name": "notify-svc"}, "payments": {"gateway_url": "x"}, "session": {"ttl": 60}}) is True

# missing section
try:
    boot({"service": {"name": "n"}, "payments": {"gateway_url": "x"}})
except BootError as e:
    print("missing ->", e)

# empty section
try:
    boot({"service": {}, "payments": {"gateway_url": "x"}, "session": {"ttl": 60}})
except BootError as e:
    print("empty ->", e)

# multiple missing
try:
    boot({})
except BootError as e:
    print("all ->", e)
EOF
